//     （unsupported Scan, storing driver.Value type <nil>），
//     那两列在作业刚建好时**正常就是 NULL**。
//
// 需要它们的报表/预算路径走 GetRelationExtractionJobPayload。
func (q *Queries) GetRelationExtractionJob(ctx context.Context, id string) (GetRelationExtractionJobRow, error) {
	row := q.db.QueryRowContext(ctx, getRelationExtractionJob, id)
	var i GetRelationExtractionJobRow
	err := row.Scan(
		&i.ID,
		&i.DocumentID,
		&i.KnowledgeBaseID,
		&i.DocumentVersion,
		&i.RunNumber,
		&i.ModelID,
		&i.ConfigHash,
		&i.SourceHash,
		&i.State,
		&i.StopReason,
		&i.Epoch,
		&i.LeaseUntil,
		&i.HeartbeatAt,
		&i.InitializationComplete,
		&i.TotalItems,
		&i.SucceededItems,
		&i.FailedItems,
		&i.ApprovedItemLimit,
		&i.CallLimit,
		&i.ActiveMsLimit,
		&i.RetryRounds,
		&i.ReservedCalls,
		&i.ConfirmedDispatches,
		&i.UnknownAttempts,
		&i.ActiveMsUsed,
		&i.ActiveMsReserved,
		&i.StartedAt,
		&i.FinishedAt,
		&i.OperationKeyHash,
		&i.OperationRequestHash,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

